/* Results are computed by Python; the static page does not train or call an ML API. */
const comparisonState={data:null,loading:false,selected:null,search:'',filter:'scored'};
const comparisonPercent=x=>x===null||x===undefined?'—':pct(x);
const comparisonSigned=x=>x===null||x===undefined?'—':(x>=0?'+':'−')+num(Math.abs(x)*100,1)+'%';
async function renderModelComparison(){
  const target=$('#pre-body');
  if(!comparisonState.data){
    target.innerHTML='<div class="panel loadscreen">Завантаження відтворюваного порівняння моделей…</div>';
    if(comparisonState.loading)return;comparisonState.loading=true;
    try{
      const response=await fetch('model-comparison.json');if(!response.ok)throw Error('Не вдалося завантажити порівняння');
      const data=await response.json();
      if(data.schema_version!==1||data.models.length!==3||!data.models.some(m=>m.key===data.selection_champion))throw Error('Несумісний звіт');
      comparisonState.data=data;comparisonState.selected=data.selection_champion;
    }catch(e){target.innerHTML=`<div class="error">${esc(e.message)}</div>`;comparisonState.loading=false;return;}
    comparisonState.loading=false;
    if(active!=='prepurchase'||preState.view!=='comparison')return;
  }
  const d=comparisonState.data,a=d.audit.phases,chosen=d.models.find(m=>m.key===comparisonState.selected),champion=d.models.find(m=>m.key===d.selection_champion);
  target.innerHTML=`<div class="comparison-intro panel"><div><span class="memo-label">ЕКСПЕРИМЕНТ · ТРИ МОДЕЛІ · ОДНАКОВІ ДАНІ</span><h2>Чи дає нейромережа кращу оцінку грошей?</h2><p>Порівнюємо Logistic + Ridge, CatBoost та нейромережу TabPFN v2. Результати реально обчислені Python-процесом; браузер показує зафіксований експеримент на синтетичній історії.</p></div><span class="chip">${esc(d.benchmark_id)}</span></div>
  <div class="metrics comparison-metrics">${metric('Обрана на валідації',esc(champion.name),'Критерій: найменша портфельна WAPE','emphasis')}${metric('Валідація для вибору',num(a.selection.count)+' <em>договорів</em>',num(a.selection.portfolios)+' портфелів · 2024')}${metric('Фінальний часовий тест',num(a.test.count)+' <em>договорів</em>',num(a.test.portfolios)+' портфелів · 2025')}${metric('Нейромережева модель','TabPFN <em>v2</em>','Локальне виконання · без ML API')}</div>
  <div class="panel table-panel comparison-table-panel"><div class="panel-heading"><div><h2>Результати на спільних вибірках</h2><p>Вибір за валідацією зафіксований до обчислення фінального тесту. Менше WAPE, MAE та Brier — краще; більше AUC — краще.</p></div><div class="download-links"><a class="button secondary" href="model-comparison.json" download>↓ Звіт JSON</a></div></div><div class="table-wrap"><table class="comparison-table"><thead><tr><th>Модель / деталі</th><th class="num">Валідація<br>WAPE портфелів</th><th class="num">Тест<br>WAPE портфелів</th><th class="num">Тест<br>MAE, ₴ / договір</th><th class="num">Тест<br>Brier</th><th class="num">Тест<br>AUC</th><th class="num">Тест<br>Помилка всіх зборів</th></tr></thead><tbody>${d.models.map(m=>`<tr class="${m.key===chosen.key?'comparison-selected':''}"><td><button class="text-button" data-candidate="${esc(m.key)}" aria-pressed="${m.key===chosen.key}">${esc(m.name)} →</button>${m.key===d.selection_champion?'<small class="comparison-tag">Обрана на валідації</small>':''}${m.key==='tabpfn'?'<small class="comparison-tag neutral">Нейромережа</small>':''}</td><td class="num">${pct(m.selection.portfolio_wape)}</td><td class="num">${pct(m.test.portfolio_wape)}</td><td class="num">${num(m.test.mae_money)}</td><td class="num">${num(m.test.brier,4)}</td><td class="num">${num(m.test.auc,3)}</td><td class="num">${comparisonSigned(m.test.gross_error_fraction)}</td></tr>`).join('')}</tbody></table></div><p class="comparison-footnote">WAPE портфелів = сума абсолютних помилок зборів кожного портфеля / сума фактичних зборів. Плюс в останній колонці означає завищення. Загальна помилка може приховувати взаємне погашення помилок окремих портфелів.</p></div>
  <div class="panel comparison-process"><h2>Чотири етапи без підглядання у фінальний тест</h2><div class="comparison-timeline">${[['train','Навчання'],['calibration','Калібрування'],['selection','Вибір моделі'],['test','Фінальний тест']].map(([key,label],i)=>`<div><span>0${i+1} · ${label.toUpperCase()}</span><strong>${esc(a[key].as_of_start)} — ${esc(a[key].as_of_end)}</strong><p>${num(a[key].count)} договорів</p><small>Результати відомі до ${esc(a[key].labels_available_until)}</small></div>`).join('')}</div><p class="fine">Усі три моделі отримали ті самі 13 ознак та однакові договори. Між етапами видалено ${num(d.audit.purged_borrowers)} перетини за позичальниками; ${num(d.audit.excluded.incomplete_outcome||0)} неповних спостережень виключено. Цілі кожного етапу відомі до початку наступного. Налаштування кандидатів зафіксовані заздалегідь.</p></div>
  <div class="two-col comparison-details"><div class="panel"><div class="panel-heading"><div><span class="memo-label">ДЕТАЛІ ОБРАНОГО РЯДКА</span><h2>${esc(chosen.name)} · калібрування на тесті</h2></div></div><p class="fine">Групи від нижчої до вищої ймовірності. Ймовірності всіх кандидатів відкалібровані на окремій групі 2023 року.</p><table><thead><tr><th>Група</th><th class="num">Кількість</th><th class="num">Середня P</th><th class="num">Частка платежів</th></tr></thead><tbody>${chosen.test.calibration_bins.map((b,i)=>`<tr><td>${i+1}</td><td class="num">${b.count}</td><td class="num">${pct(b.predicted)}</td><td class="num">${pct(b.observed)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>${esc(chosen.name)} · перевірка за продавцями</h2><p class="fine">Синтетичні продавці фінального тесту. Це діагностика, а не незалежний тест перенесення на нового продавця.</p><table><thead><tr><th>Продавець</th><th class="num">Договорів</th><th class="num">Помилка зборів</th></tr></thead><tbody>${chosen.test.sellers.map(s=>`<tr><td>${esc(s.seller_id)}</td><td class="num">${num(s.count)}</td><td class="num">${comparisonSigned(s.gross_error_fraction)}</td></tr>`).join('')}</tbody></table><h3>Скільки прогнозовано понад факт</h3><p class="comparison-large">${pct(chosen.test.overestimate_fraction)}</p><p class="fine">Сума тільки додатних помилок портфелів / фактичні збори тесту. Це показник завищення валових надходжень; ризик завищення ціни ще потребує строків і витрат.</p><h3>Налаштування експерименту</h3><p class="fine">${chosen.key==='baseline'?'Logistic C=1; Ridge α=10; масштабування лише на навчанні.':chosen.key==='catboost'?'250 дерев; глибина 4; learning rate 0,035; L2=8. Окремі моделі ймовірності та частки погашення.':'Попередньо навчений трансформер TabPFN v2; один учасник ансамблю; CPU; контекст лише з навчальних договорів. Це обмежений за обчисленнями експеримент, а не повний пошук налаштувань.'}</p></div></div>
  <div class="panel comparison-case"><div class="panel-heading"><div><span class="memo-label">ПОТОЧНИЙ ДЕМОПАКЕТ · 12 МІСЯЦІВ</span><h2>${esc(chosen.name)} · прогноз за договорами</h2><p>Пакет із ${num(chosen.current.total)} договорів. Оцінено ${num(chosen.current.scored)}; без прогнозу ${num(chosen.current.total-chosen.current.scored)}. Очікувані валові збори: <b>${money(chosen.current.expected_gross)}</b>.</p></div><button class="button primary" data-action="comparison-export">↓ Прогноз ${esc(chosen.name)} CSV</button></div><div class="toolbar"><input id="comparison-search" type="search" aria-label="Пошук у порівнянні" placeholder="ID договору" value="${esc(comparisonState.search)}"><select id="comparison-filter" aria-label="Статус у порівнянні"><option value="scored" ${comparisonState.filter==='scored'?'selected':''}>Оцінені договори</option><option value="review" ${comparisonState.filter==='review'?'selected':''}>Без прогнозу — перевірка</option><option value="all" ${comparisonState.filter==='all'?'selected':''}>Усі договори</option></select></div><div class="table-wrap"><table><thead><tr><th>Договір</th><th>Сегмент</th><th class="num">P(платіж)</th><th class="num">Сума при платежі</th><th class="num">Очікувана сума</th><th>Статус</th></tr></thead><tbody id="comparison-rows"></tbody></table></div><div class="pager"><span id="comparison-count"></span><span>Показано до 30 записів</span></div></div>
  <div class="notice comparison-limit"><b>Межі висновків.</b> Обрання моделі на одній синтетичній валідації не доводить її перевагу на українському ринку. Навчання на реальній дозволеній історії та повторні часові перевірки потрібні перед застосуванням. Імпортований JSON у вкладці «Прогноз пакета» оцінюється попередньою базовою моделлю; цей екран показує фіксований демопакет. Прогнози — валові за 12 місяців; строки, витрати і ціна покупки тут не моделюються.</div>
  <div class="panel comparison-downloads"><div><h2>Відтворити та адаптувати</h2><p class="fine">Python навчає кандидатів, обирає модель і оцінює новий JSON локально. Сайт показує готові результати; важкі моделі в браузері не запускаються.</p><p class="fine">Built with <a href="https://github.com/PriorLabs/TabPFN" target="_blank" rel="noopener">TabPFN · Prior Labs</a>. Ваги v2 завантажуються окремо.</p><p class="fine">Версії: ${Object.entries(d.versions).map(([k,v])=>esc(k)+' '+esc(v)).join(' · ')}</p></div><div class="download-links"><a class="button secondary" href="demo-source.zip" download>↓ Код, тести та інструкція</a><a class="button secondary" href="model-bundle.json" download>↓ Артефакти моделей</a><a class="button secondary" href="benchmark-history.json" download>↓ Історія порівняння</a></div></div>`;
  renderComparisonRows();
}
function renderComparisonRows(){
  const model=comparisonState.data.models.find(m=>m.key===comparisonState.selected);
  const rows=model.current.scores.filter(s=>(comparisonState.filter==='all'||(comparisonState.filter==='scored'?s.status==='scored':s.status!=='scored'))&&(!comparisonState.search||s.loan_id.toLowerCase().includes(comparisonState.search.toLowerCase()))).sort((a,b)=>(b.expected??-1)-(a.expected??-1));
  $('#comparison-rows').innerHTML=rows.slice(0,30).map(s=>`<tr><td><b>${esc(s.loan_id)}</b></td><td>${esc(NPL.SEGMENTS[s.segment].label)}</td><td class="num">${comparisonPercent(s.probability)}</td><td class="num">${s.conditional===null?'—':money(s.conditional)}</td><td class="num">${s.expected===null?'—':money(s.expected)}</td><td>${s.status==='scored'?'Оцінено':`<span class="badge review">${esc(PRE_REASONS[s.status])}</span>`}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">За цими умовами записів немає.</td></tr>';
  $('#comparison-count').textContent=num(rows.length)+' договорів';
}
function comparisonMemo(){
  const d=comparisonState.data;if(!d)return '<article class="memo"><p>Порівняння ще завантажується.</p></article>';
  const champion=d.models.find(m=>m.key===d.selection_champion),selected=d.models.find(m=>m.key===comparisonState.selected);
  return `<article class="memo"><div class="memo-label">ПОРІВНЯННЯ МОДЕЛЕЙ · ЛИШЕ СИНТЕТИЧНІ ДАНІ</div><h2>Logistic + Ridge / CatBoost / TabPFN v2</h2><p>Експеримент ${esc(d.benchmark_id)}. Кандидат за найменшою портфельною WAPE на валідації: <b>${esc(champion.name)}</b>. Результат фінального тесту не змінює цей вибір.</p><table><thead><tr><th>Модель</th><th>Валідація WAPE</th><th>Тест WAPE</th><th>Тест MAE, ₴</th><th>Тест Brier</th></tr></thead><tbody>${d.models.map(m=>`<tr><td>${esc(m.name)}</td><td>${pct(m.selection.portfolio_wape)}</td><td>${pct(m.test.portfolio_wape)}</td><td>${num(m.test.mae_money)}</td><td>${num(m.test.brier,4)}</td></tr>`).join('')}</tbody></table><h3>Поточний демопакет · ${esc(selected.name)}</h3><p>Оцінено ${num(selected.current.scored)} із ${num(selected.current.total)} договорів. Прогноз валових зборів за 12 місяців: ${money(selected.current.expected_gross)}.</p><h3>Метод та обмеження</h3><p>Чотири хронологічні групи: навчання, калібрування ймовірностей, вибір моделі, фінальний тест. Позичальники між групами не перетинаються. Усі моделі використовують лише інформацію, доступну до угоди. Прогноз = ймовірність платежу × сума за умови платежу.</p><p>Результати синтетичні й не підтверджують придатність для українських портфелів. Поточний пакет фіксований, не імпортований. Витрати, строки та ціна покупки не включені. Для реального застосування потрібні дозволені місцеві дані та незалежна перевірка.</p><small>Sergey Golubev · NPL Investment Lab</small></article>`;
}
function exportComparisonScores(){
  const d=comparisonState.data,model=d.models.find(m=>m.key===comparisonState.selected);
  const fields=['loan_id','segment','as_of_date','horizon_end','status','probability','conditional','expected','unseen_seller'];
  const cell=v=>{if(v===null||v===undefined)return '';let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
  const lines=[['benchmark_id','model','artifact_id','synthetic_training',...fields].join(','),...model.current.scores.map(s=>[d.benchmark_id,model.key,model.artifact_id,true,...fields.map(k=>s[k])].map(cell).join(','))];
  download('npl-'+model.key+'-12m.csv','\uFEFF'+lines.join('\r\n'),'text/csv;charset=utf-8');toast('Прогноз '+model.name+' експортовано.');
}
document.addEventListener('click',e=>{
  const model=e.target.closest('[data-candidate]');if(model){comparisonState.selected=model.dataset.candidate;renderModelComparison();}
  if(e.target.closest('[data-action="comparison-export"]'))exportComparisonScores();
});
document.addEventListener('input',e=>{if(e.target.id==='comparison-search'){comparisonState.search=e.target.value;renderComparisonRows();}});
document.addEventListener('change',e=>{if(e.target.id==='comparison-filter'){comparisonState.filter=e.target.value;renderComparisonRows();}});
